def solve(coins, amount):
    # DP for unbounded coin change: minimum number of coins to make each value up to amount.
    # Initialize dp array with a large number (amount+1 is sufficient as max coins needed).
    if amount < 0:
        return -1
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        if coin <= 0:
            # ignore non-positive coin values to avoid infinite loops
            continue
        for x in range(coin, amount + 1):
            # If using this coin improves the count, take it.
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1
    return dp[amount] if dp[amount] != amount + 1 else -1

