def solve(coins, amount):
    """Return the minimum number of coins needed to make `amount` using unlimited
    coins from `coins`. Return -1 if impossible.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Keep only positive distinct coin values.
    coins = [c for c in set(coins) if c > 0]
    if not coins:
        return -1
    # Quick impossibility check using gcd.
    from math import gcd
    g = 0
    for c in coins:
        g = gcd(g, c)
    if amount % g != 0:
        return -1
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        for x in range(coin, amount + 1):
            # If we can reach x-coin, using this coin yields one more coin.
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1
    return dp[amount] if dp[amount] != INF else -1

