def solve(coins, amount):
    """Return the minimum number of coins needed to make `amount` using unlimited
    coins from `coins`. Return -1 if impossible.
    Handles edge cases efficiently, including a fast path when a coin of value 1
    is present, avoiding large DP tables.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Keep distinct positive coin values only.
    coins = [c for c in set(coins) if c > 0]
    if not coins:
        return -1
    # Fast path: coin of value 1 can compose any amount using exactly `amount` coins.
    if 1 in coins:
        return amount
    # If the greatest common divisor of all coins does not divide amount, impossible.
    from math import gcd
    g = 0
    for c in coins:
        g = gcd(g, c)
    if amount % g != 0:
        return -1
    # Dynamic programming (unbounded knapsack) for minimal coin count.
    INF = amount + 1  # sentinel larger than any possible result
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        for x in range(coin, amount + 1):
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1
    return dp[amount] if dp[amount] != INF else -1

