def solve(grid):
    """Count the number of islands (connected components of 1s) in a possibly jagged grid.
    4-directional adjacency (up, down, left, right)."""
    if not grid:
        return 0
    visited = set()
    rows = len(grid)
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            visited.add((i, j))
            # explore neighbors
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ni, nj = i + di, j + dj
                if 0 <= ni < rows and 0 <= nj < len(grid[ni]):
                    if grid[ni][nj] == 1 and (ni, nj) not in visited:
                        stack.append((ni, nj))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

