def solve(s):
    """Robust Roman numeral to integer conversion.
    Handles uppercase/lowercase, ignores whitespace, and safely returns 0 for
    any unexpected characters. Uses the standard subtract‑add rule.
    """
    vals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    # Normalize and filter only valid Roman characters
    filtered = [ch for ch in s.upper() if ch in vals]
    if not filtered:
        return 0
    total = 0
    n = len(filtered)
    for i, ch in enumerate(filtered):
        v = vals[ch]
        if i + 1 < n and v < vals[filtered[i + 1]]:
            total -= v
        else:
            total += v
    return total

