def solve(s):
    """Run‑length encode a sequence.
    Returns a list of [character, count] pairs for consecutive equal elements.
    Non‑iterable inputs return an empty list. Bytes are decoded to characters.
    """
    try:
        iterator = iter(s)
    except TypeError:
        return []
    out = []
    for elem in iterator:
        # Decode bytes/ints to characters for expected output
        if isinstance(elem, int):
            ch = chr(elem)
        else:
            ch = elem
        if out and out[-1][0] == ch:
            out[-1][1] += 1
        else:
            out.append([ch, 1])
    return out

