def solve(n):
    if n <= 2:
        return 0
    sieve = [True] * n
    sieve[0] = sieve[1] = False
    import math
    for i in range(2, int(math.isqrt(n-1)) + 1):
        if sieve[i]:
            step = i
            start = i*i
            sieve[start:n:step] = [False] * ((n - start - 1)//step + 1)
    return sum(sieve)

