def solve(coins, amount):
    """Return the minimum number of coins needed to make ``amount`` using unlimited
    copies of the positive coin denominations in ``coins``. Return -1 if impossible.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Filter out non‑positive values and deduplicate
    coins = [c for c in set(coins) if c > 0]
    if not coins:
        return -1
    INF = amount + 1  # larger than any possible count
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        for x in range(coin, amount + 1):
            # If amount x-coin can be made, using this coin yields one more.
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1
    return dp[amount] if dp[amount] != INF else -1

