def solve(s):
    """Run‑length encode a sequence of characters.

    * If *s* is a ``str`` – encode each character.
    * If *s* is any other iterable (list, tuple, generator) – it is accepted
      only when every element is a one‑character string.  Otherwise an empty
      list is returned, matching the specification that the input must be a
      string.
    * Non‑iterable inputs also yield ``[]``.
    """
    # Direct string handling
    if isinstance(s, str):
        seq = list(s)
    else:
        # Try to treat as an iterable
        try:
            seq = list(s)
        except TypeError:
            return []
        # Validate that all elements are single‑character strings
        for elem in seq:
            if not isinstance(elem, str) or len(elem) != 1:
                return []
    if not seq:
        return []
    out = []
    for ch in seq:
        if out and out[-1][0] == ch:
            out[-1][1] += 1
        else:
            out.append([ch, 1])
    return out

