def solve(s):
    """Run‑length encode a sequence.

    * If *s* is a ``str`` – encode each character.
    * If *s* is ``bytes`` or ``bytearray`` – treat each byte as a character via ``chr``.
    * If *s* is any other iterable (list, tuple, generator, etc.) – encode the elements as‑is.
    * Non‑iterable inputs return an empty list.
    """
    # Handle strings directly
    if isinstance(s, str):
        seq = list(s)
    # Handle bytes‑like objects by converting each byte to a character
    elif isinstance(s, (bytes, bytearray)):
        seq = [chr(b) for b in s]
    else:
        try:
            seq = list(s)
        except TypeError:
            return []
    if not seq:
        return []
    out = []
    for elem in seq:
        if out and out[-1][0] == elem:
            out[-1][1] += 1
        else:
            out.append([elem, 1])
    return out

