def solve(matrix):
    """Return the elements of *matrix* in clockwise spiral order.
    Handles empty matrices and matrices with a single row or column.
    """
    if not matrix:
        return []
    # Ensure matrix is rectangular; if rows have varying lengths, treat missing as end.
    rows = len(matrix)
    cols = len(matrix[0])
    # If any row shorter, adjust cols to min length to avoid IndexError.
    for r in matrix:
        if len(r) < cols:
            cols = len(r)
    top, bottom = 0, rows - 1
    left, right = 0, cols - 1
    result = []
    while top <= bottom and left <= right:
        # top row
        for c in range(left, right + 1):
            result.append(matrix[top][c])
        top += 1
        # right column
        for r in range(top, bottom + 1):
            result.append(matrix[r][right])
        right -= 1
        if top <= bottom:
            # bottom row (right to left)
            for c in range(right, left - 1, -1):
                result.append(matrix[bottom][c])
            bottom -= 1
        if left <= right:
            # left column (bottom to top)
            for r in range(bottom, top - 1, -1):
                result.append(matrix[r][left])
            left += 1
    return result

